window.docContents[154].resolve({"/Stlc/#Type-Systems--Stlc___-The-Simply-Typed-Lambda-Calculus--Operational-Semantics":{"contents":"To define the small-step semantics of STLC terms, we begin,\nas always, by defining the set of values.  Next, we define the\ncritical notions of free variables and substitution, which are\nused in the reduction rule for application expressions.  And\nfinally we give the small-step relation itself.\n\n\n\n\n\n\n\n\n\n\n\n\n\n","context":"Type Systems\u0009Stlc: The Simply Typed Lambda-Calculus","header":"5.3. Operational Semantics","id":"/Stlc/#Type-Systems--Stlc___-The-Simply-Typed-Lambda-Calculus--Operational-Semantics"}});